script.setup:
async function setup(ctx) {
  const fs = `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 outColor;

uniform float u_time;
uniform vec2 u_resolution;
uniform float u_speed;
uniform float u_ringScale;
uniform float u_glow;
uniform vec3 u_orange;

void main() {
  vec2 uv = v_uv * 2.0 - 1.0;
  uv.x *= u_resolution.x / u_resolution.y;

  float r = length(uv);
  float t = u_time * u_speed;

  float waves = fract(r * u_ringScale - t);
  float ring = smoothstep(0.12, 0.0, abs(waves - 0.18));
  float softRing = smoothstep(0.34, 0.0, abs(waves - 0.18)) * 0.35;

  float centerPulse = exp(-r * 3.4) * (0.35 + 0.22 * sin(t * 3.14159));
  float fade = smoothstep(1.55, 0.15, r);
  float vignette = smoothstep(1.35, 0.25, r);

  vec3 bg = vec3(0.035, 0.012, 0.002);
  vec3 ember = u_orange * (ring * (1.2 + u_glow) + softRing * u_glow + centerPulse);
  vec3 color = bg + ember * fade;
  color += vec3(1.0, 0.33, 0.02) * pow(max(0.0, 1.0 - r), 3.0) * 0.3;
  color *= 0.72 + 0.28 * vignette;

  outColor = vec4(color, 1.0);
}`;
  ctx.state.program = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs);
}

setup(ctx);
